const providerPinIcon = (selected: boolean, kind: "service" | "provider" = "provider") => {
  const scale = selected ? 1.2 : 1;
  const width = Math.round(45 * scale);
  const height = Math.round(59 * scale);
  const glyph =
    kind === "service" ? SERVICE_GLYPH : providerGlyph(`pinclip-${Math.random().toString(36).slice(2)}`);
  return divIcon({
    className: "",
    html: `<svg width="${width}" height="${height}" viewBox="0 0 45 59" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="${PIN_OUTLINE}" fill="#0079FF"/>
      ${glyph}
    </svg>`,
    iconSize: [width, height],
    iconAnchor: [width / 2, height],
  });
};

const clusterPinIcon = (label: string, selected: boolean) => {
  const scale = selected ? 1.2 : 1;
  const width = Math.round(45 * scale);
  const height = Math.round(59 * scale);
  return divIcon({
    className: "",
    html: `<svg width="${width}" height="${height}" viewBox="0 0 45 59" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="${PIN_OUTLINE}" fill="#0079FF"/>
      <text x="22.5" y="24" text-anchor="middle" dominant-baseline="middle" fill="white" font-family="sans-serif" font-weight="700" font-size="16">${label}</text>
    </svg>`,
    iconSize: [width, height],
    iconAnchor: [width / 2, height],
  });
};

function RecenterOnChange({ center }: { center: LocationMapProps["center"] }) {
  const map = useMap();
  useEffect(() => {
    map.setView(center);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- recenter on lat/lng values, not object identity
  }, [map, center.lat, center.lng]);
  return null;
}

// Leaflet computes its container's pixel size once at init and never re-checks it.
// Inside a Dialog that animates/mounts, the container's real size isn't final yet at
// that point, so drag/click coordinate math silently uses stale dimensions even
// though the tiles still render fine visually. Force a recalculation once the
// container has settled, and again on window resize.
function InvalidateSizeOnMount() {
  const map = useMap();
  useEffect(() => {
    const timer = setTimeout(() => map.invalidateSize(), 250);
    const handleResize = () => map.invalidateSize();
    window.addEventListener("resize", handleResize);
    return () => {
      clearTimeout(timer);
      window.removeEventListener("resize", handleResize);
    };
  }, [map]);
  return null;
}

// Softens the raw OSM tiles (light mode only — the dark tileset is already
// styled) to match the app's muted map look instead of stock OSM's saturated
// colors.
function LightTileFilter() {
  const map = useMap();
  useEffect(() => {
    const pane = map.getPane("tilePane");
    if (pane) pane.style.filter = "grayscale(1) brightness(1.08) contrast(0.92)";
    return () => {
      if (pane) pane.style.filter = "";
    };
  }, [map]);
  return null;
}

function DraggableMarker({
  center,
  onCenterChange,
  onBackgroundClick,
}: Pick<LocationMapProps, "center" | "onCenterChange" | "onBackgroundClick">) {
  useMapEvents({
    click(event) {
      onCenterChange?.({ lat: event.latlng.lat, lng: event.latlng.lng });
      onBackgroundClick?.();
    },
  });

  return (
    <Marker
      position={center}
      icon={pinIcon}
      draggable={Boolean(onCenterChange)}
      eventHandlers={{
        dragend: (event) => {
          const marker = event.target;
          const position = marker.getLatLng();
          onCenterChange?.({ lat: position.lat, lng: position.lng });
        },
      }}
    />
  );
}

export function OsmLocationMap({
  center,
  zoom = 14,
  onCenterChange,
  className,
  pins,
  onPinClick,
  onBackgroundClick,
}: LocationMapProps) {
  const isDark = useIsDarkMode();

  return (
    <MapContainer
      center={center}
      zoom={zoom}
      className={className ?? "size-full"}
      scrollWheelZoom
    >
      {isDark ? (
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
          url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
        />
      ) : (
        <>
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            subdomains={["a", "b", "c"]}
            maxZoom={19}
          />
          <LightTileFilter />
        </>
      )}
      <DraggableMarker
        center={center}
        onCenterChange={onCenterChange}
        onBackgroundClick={onBackgroundClick}
      />
      <RecenterOnChange center={center} />
      <InvalidateSizeOnMount />
      {pins?.map((pin) => (
        <Marker
          key={pin.id}
          position={pin.position}
          icon={
            pin.label
              ? clusterPinIcon(pin.label, Boolean(pin.selected))
              : providerPinIcon(Boolean(pin.selected), pin.kind)
          }
          eventHandlers={{
            click: () => onPinClick?.(pin.id),
          }}
        />
      ))}
    </MapContainer>
  );
}
